function mergeSeed(saved){const d=seed();if(!saved||typeof saved!=='object')return d;const merged={...d,...saved,version:4,profiles:{...d.profiles,...saved.profiles},settings:{...d.settings,...saved.settings},messages:{...d.messages,...saved.messages},groups:{...d.groups,...saved.groups},chatThemes:{...d.chatThemes,...saved.chatThemes},dev:{...d.dev,...saved.dev},accountConnections:{...d.accountConnections,...saved.accountConnections}};merged.archivedChats=Array.isArray(saved.archivedChats)?saved.archivedChats:[];merged.chatFilter=saved.chatFilter==='archived'?'archived':'inbox';merged.accounts=Array.isArray(saved.accounts)&&saved.accounts.length?saved.accounts:['me'];if(!merged.accountConnections[merged.meId])merged.accountConnections[merged.meId]=Array.isArray(saved.connected)?saved.connected:[];merged.connected=[...merged.accountConnections[merged.meId]];return merged}
function load(){try{let raw=localStorage.getItem(STORE);if(!raw){for(const k of LEGACY_STORES){raw=localStorage.getItem(k);if(raw)break}}return mergeSeed(raw?JSON.parse(raw):null)}catch{return seed()}}
function prune(){const n=now();state.moments=(state.moments||[]).filter(m=>!m.createdAt||n-m.createdAt<86400000);Object.keys(state.messages||{}).forEach(k=>state.messages[k]=(state.messages[k]||[]).filter(m=>!m.expiresAt||m.expiresAt>n));Object.values(state.groups||{}).forEach(g=>g.messages=(g.messages||[]).filter(m=>!m.expiresAt||m.expiresAt>n));state.archivedChats=(state.archivedChats||[]).filter(id=>id&&id!==state.meId);}
function switchAccount(pid){if(!state.profiles[pid])return;state.accountConnections=state.accountConnections||{};state.accountConnections[state.meId]=[...(state.connected||[])];state.meId=pid;state.connected=[...(state.accountConnections[pid]||[])];state.tab='feed';state.profileTab='posts';currentChat=null;currentMoment=null;contextMsg=null;replyingTo=null;save()}
function formatTimer(sec){if(!sec)return'Off';if(sec<60)return`${sec}s`;if(sec<3600)return`${Math.round(sec/60)}m`;if(sec<86400)return`${Math.round(sec/3600)}h`;return`${Math.round(sec/86400)}d`}
