 on('[data-simulate-scan]',()=>{const u=qs('#scanUser').value.trim().toLowerCase();const p=Object.values(state.profiles).find(x=>x.username.toLowerCase()===u);if(!p)return toast('No local account found');overlay={type:'profile',id:p.id};app()});
